#!/usr/bin/env bash
# ADR-0009, ADR-0017: the secrets utility's own tests, with no real secret
# (keys are placeholders, or are generated by tests/e2e.sh and thrown away):
#   schema        tests/schema.nix: the registry schema, its reports, every
#                 assertion's message (lib.secrets.evalRegistry)
#   template      templates/data evaluates and `secrets check` passes on it
#   nixos-module  nixosModules.secrets: the identity default, a host's own value wins
#   e2e           tests/e2e.sh: a data repository with generated keys, real sops
# Needs python3, git, ripgrep, sops, age, ssh-to-age and ssh-keygen on PATH
# (tools/gates.sh runs it in a nix shell of them). One JSON line on stdout.
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT" || exit 2
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
fail=0
say() { printf 'secrets: %s\n' "$*" >&2; }

# The flake as committed plus the working tree's tracked files.
FLAKE="git+file://$ROOT"
ev() { nix eval --impure --json --expr "let f = builtins.getFlake \"$FLAKE\"; lib = f.inputs.nixpkgs.lib; in $1"; }

# --- schema ---------------------------------------------------------------------
if ev 'import ./tests/schema.nix { inherit lib; self = f; }' >"$T/schema.json" 2>"$T/schema.err"; then
  if python3 - "$T/schema.json" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
for m in d["failed"]:
    print("secrets: schema FAIL " + m, file=sys.stderr)
print(f"secrets: schema {len(d['passed'])} passed, {len(d['failed'])} failed", file=sys.stderr)
sys.exit(1 if d["failed"] or not d["passed"] else 0)
PY
  then :; else fail=1; fi
else
  say "schema FAIL: evaluation"; tail -n 20 "$T/schema.err" >&2; fail=1
fi

# --- template -------------------------------------------------------------------
if ev '(f.lib.secrets.evalRegistry { registry = ./templates/data/registry.nix; }).checkReport { }' >"$T/template.json" 2>"$T/template.err"; then
  if HOME="$T" python3 tools/secrets-check.py --report "$T/template.json" --root templates/data >"$T/template.out" 2>&1; then
    say "template: pass"
  else
    say "template FAIL"; cat "$T/template.out" >&2; fail=1
  fi
else
  say "template FAIL: evaluation"; tail -n 20 "$T/template.err" >&2; fail=1
fi

# --- nixos-module ---------------------------------------------------------------
NM='let
  mk = extra: (lib.nixosSystem {
    modules = [ f.nixosModules.secrets { nixpkgs.hostPlatform = "x86_64-linux"; boot.isContainer = true; system.stateVersion = "25.05"; } ] ++ extra;
  }).config.sops.age.sshKeyPaths;
in [ (mk [ ]) (mk [ { sops.age.sshKeyPaths = [ "/persist/ssh_host_ed25519_key" ]; } ]) ]'
if ev "$NM" >"$T/nm.json" 2>"$T/nm.err" \
  && [[ "$(cat "$T/nm.json")" == '[["/etc/ssh/ssh_host_ed25519_key"],["/persist/ssh_host_ed25519_key"]]' ]]; then
  say "nixos-module: pass"
else
  say "nixos-module FAIL: $(cat "$T/nm.json" 2>/dev/null)"; tail -n 20 "$T/nm.err" >&2; fail=1
fi

# --- e2e ------------------------------------------------------------------------
NIXPKGS_LIB="$(nix eval --impure --raw --expr "(builtins.getFlake \"$FLAKE\").inputs.nixpkgs.outPath" 2>"$T/lib.err")/lib"
if NIXPKGS_LIB="$NIXPKGS_LIB" bash tests/e2e.sh >&2; then :; else say "e2e FAIL"; fail=1; fi

if ((fail)); then echo '{"secrets":"fail"}'; exit 1; fi
echo '{"secrets":"pass"}'
